package com.univmar.project.api; import com.univmar.project.domain.ProjectStatus; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.Page;
public final class ProjectDtos {private ProjectDtos(){} public record ProjectInput(@NotNull UUID customerId,@NotBlank String name,String location,String projectType,String description,@DecimalMin("0.00") BigDecimal estimatedValue,LocalDate startDate,LocalDate requiredDeliveryDate,String assignedSalesAgent,@NotNull ProjectStatus status,String notes){} public record ProjectImageInput(@NotBlank @Size(max=1000) String imageUrl,@Size(max=240) String caption){} public record ProjectImageResponse(UUID id,String imageUrl,String caption,int position,Instant createdAt){} public record ProjectResponse(UUID id,UUID customerId,String customerName,String name,String location,String projectType,String description,BigDecimal estimatedValue,LocalDate startDate,LocalDate requiredDeliveryDate,String assignedSalesAgent,ProjectStatus status,String notes,List<ProjectImageResponse> images){} public record ProjectPage(List<ProjectResponse> content,int page,int size,long totalElements,int totalPages){public static ProjectPage from(Page<ProjectResponse> p){return new ProjectPage(p.getContent(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}}}
